<script setup lang="ts">
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import type { CatalogoRendicionCajaChica, DestinoRendicionCajaChica, DocumentoRendicionCajaChica, DocumentoRendicionCajaChicaPayload, FondoCajaChicaResumen, PersonaRendicionCajaChica, TipoRendicionCajaChica } from '../interfaces/rendicion-caja-chica.interface'
import { buscarPersonasRendicion, guardarRendicionCajaChica, listarFondosPorRendicion, obtenerOpcionesRendicionCajaChica, obtenerRendicionCajaChica, obtenerSiguienteNumeroRendicion } from '../services/rendicion-caja-chica'
const router=useRouter(),route=useRoute(),rendicionId=Number(route.params.id)||null,isEditing=Boolean(Number(route.params.id)),today=new Date().toISOString().slice(0,10),listPath='/modulos/administracion/finanzas/rendiciones-caja-chica'
const header=reactive({tipo_rendicion:'' as TipoRendicionCajaChica|'',tipo_fondo_caja_chica_id:0,numero_rendicion:'',fecha:today,referencia:''})
const documents=ref<DocumentoRendicionCajaChicaPayload[]>([]),funds=ref<FondoCajaChicaResumen[]>([]),documentTypes=ref<CatalogoRendicionCajaChica[]>([]),categories=ref<CatalogoRendicionCajaChica[]>([]),destinations=ref<DestinoRendicionCajaChica[]>([]),modal=ref(false),editing=ref<number|null>(null),loading=ref(false),saving=ref(false),error=ref(''),personQuery=ref(''),people=ref<PersonaRendicionCajaChica[]>([]),searching=ref(false)
const blank=():DocumentoRendicionCajaChicaPayload=>({documento_caja_chica_id:0,serie:'',numero:'',fecha_documento:today,tipo_persona:'PROVEEDOR',proveedor_id:null,trabajador_id:null,codigo_persona:'',nombre_persona:'',subtotal:0,impuesto:0,otros:0,total:0,rubro_caja_chica_id:null,destino_movilidad_id:null,glosa:''})
const doc=reactive(blank()),money=(v:number)=>new Intl.NumberFormat('es-PE',{minimumFractionDigits:2,maximumFractionDigits:2}).format(v),message=(v:unknown)=>v instanceof Error?v.message:'No se pudo completar la operación.'
const totals=computed(()=>documents.value.reduce((a,d)=>({subtotal:a.subtotal+d.subtotal,impuesto:a.impuesto+d.impuesto,otros:a.otros+d.otros,total:a.total+d.total}),{subtotal:0,impuesto:0,otros:0,total:0}))
function calculate(){doc.subtotal=Number(doc.subtotal)||0;doc.impuesto=Number(doc.impuesto)||0;doc.otros=Number(doc.otros)||0;doc.total=doc.subtotal+doc.impuesto+doc.otros}
async function loadOptions(){loading.value=true;try{const d=await obtenerOpcionesRendicionCajaChica();documentTypes.value=d.documentos_caja_chica;categories.value=d.rubros_caja_chica;destinations.value=d.destinos_movilidad}catch(e){error.value=message(e)}finally{loading.value=false}}
function payloadDocument(x:DocumentoRendicionCajaChica):DocumentoRendicionCajaChicaPayload{return {documento_caja_chica_id:x.documento_caja_chica_id,serie:x.serie??'',numero:x.numero??'',fecha_documento:(x.fecha_documento??today).slice(0,10),tipo_persona:x.tipo_persona??'PROVEEDOR',proveedor_id:x.proveedor_id??null,trabajador_id:x.trabajador_id??null,codigo_persona:x.codigo_persona??'',nombre_persona:x.nombre_persona??'',subtotal:Number(x.subtotal)||0,impuesto:Number(x.impuesto)||0,otros:Number(x.otros)||0,total:Number(x.total)||0,rubro_caja_chica_id:x.rubro_caja_chica_id??null,destino_movilidad_id:x.destino_movilidad_id??null,glosa:x.glosa??''}}
async function loadRendicion(){if(!rendicionId)return;loading.value=true;try{const x=await obtenerRendicionCajaChica(rendicionId);if(!x.activo){error.value='Las rendiciones anuladas son de solo lectura.';return}header.tipo_rendicion=x.tipo_rendicion;header.tipo_fondo_caja_chica_id=x.tipo_fondo_caja_chica_id;header.numero_rendicion=String(x.numero_rendicion).padStart(3,'0');header.fecha=x.fecha.slice(0,10);header.referencia=x.referencia??'';funds.value=(await listarFondosPorRendicion(x.tipo_rendicion)).data;documents.value=(x.documentos??[]).map(payloadDocument)}catch(e){error.value=message(e)}finally{loading.value=false}}
async function changeType(){header.tipo_fondo_caja_chica_id=0;header.numero_rendicion='';funds.value=[];if(!header.tipo_rendicion)return;loading.value=true;try{const [f,n]=await Promise.all([listarFondosPorRendicion(header.tipo_rendicion),obtenerSiguienteNumeroRendicion(header.tipo_rendicion)]);funds.value=f.data;header.numero_rendicion=n.numero_formateado}catch(e){error.value=message(e)}finally{loading.value=false}}
function open(i?:number){editing.value=i??null;Object.assign(doc,i===undefined?blank():documents.value[i]);personQuery.value='';people.value=[];modal.value=true}
function resetPerson(){doc.proveedor_id=null;doc.trabajador_id=null;doc.codigo_persona='';doc.nombre_persona='';people.value=[]}
async function search(){if(personQuery.value.trim().length<2)return;searching.value=true;try{people.value=await buscarPersonasRendicion(doc.tipo_persona,personQuery.value.trim())}catch(e){error.value=message(e)}finally{searching.value=false}}
function selectPerson(p:PersonaRendicionCajaChica){doc.codigo_persona=p.codigo;doc.nombre_persona=p.nombre;if(doc.tipo_persona==='PROVEEDOR')doc.proveedor_id=p.id;else doc.trabajador_id=p.id;people.value=[]}
function saveDocument(){calculate();if(!doc.documento_caja_chica_id||!doc.fecha_documento)return error.value='Complete el tipo y la fecha del documento.';if(!doc.codigo_persona)return error.value='Seleccione un proveedor o trabajador.';if(doc.total<=0)return error.value='El total debe ser mayor a cero.';const item={...doc};if(editing.value===null)documents.value.push(item);else documents.value[editing.value]=item;modal.value=false;error.value=''}
function remove(i:number){if(confirm('¿Desea quitar este documento?'))documents.value.splice(i,1)}
async function submit(){error.value='';if(!header.tipo_rendicion)return error.value='Seleccione el tipo de rendición.';if(!header.tipo_fondo_caja_chica_id)return error.value='Seleccione el fondo fijo.';if(!documents.value.length)return error.value='Debe agregar al menos un documento.';saving.value=true;try{await guardarRendicionCajaChica({tipo_rendicion:header.tipo_rendicion,tipo_fondo_caja_chica_id:header.tipo_fondo_caja_chica_id,fecha:header.fecha,referencia:header.referencia,documentos:documents.value},rendicionId??undefined);await router.push(listPath)}catch(e){error.value=message(e)}finally{saving.value=false}}
onMounted(async()=>{await loadOptions();await loadRendicion()})
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / <RouterLink :to="listPath">Rendiciones</RouterLink> / {{isEditing?'Editar':'Nueva'}}</nav><header class="hero"><b>RC</b><div><small>MIA · FINANZAS · CAJA CHICA</small><h1>{{isEditing?'Editar':'Nueva'}} rendición de caja chica</h1><p>{{isEditing?'Actualice la cabecera y sus documentos sustentatorios.':'Registre la cabecera y sus documentos sustentatorios.'}}</p></div></header><p v-if="error" class="flash">{{error}}</p><form @submit.prevent="submit"><section class="card"><h2>Cabecera de la rendición</h2><div class="grid"><label>Tipo de rendición *<select v-model="header.tipo_rendicion" @change="changeType"><option value="">Seleccione</option><option value="FONDO_FIJO">Fondo fijo</option><option value="GASTO_DIRECTO">Gasto directo</option><option value="ANTICIPO_VIATICO">Anticipos - viáticos</option></select></label><label>Fondo fijo *<select v-model.number="header.tipo_fondo_caja_chica_id"><option :value="0">Seleccione</option><option v-for="x in funds" :key="x.id" :value="x.id">{{x.codigo}} · {{x.detalle}}</option></select></label><label>Nro. rendición<input :value="header.numero_rendicion" readonly placeholder="Automático"></label><label>Fecha *<input v-model="header.fecha" type="date"></label><label class="full">Referencia<input v-model="header.referencia" maxlength="250"></label></div></section><section class="card"><header><h2>Documentos registrados</h2><button type="button" @click="open()">+ Agregar documento</button></header><div v-if="!documents.length" class="empty">No hay documentos agregados.</div><div v-else class="scroll"><table><thead><tr><th>Documento</th><th>Fecha</th><th>Persona</th><th>Rubro / destino</th><th>Subtotal</th><th>Impuesto</th><th>Otros</th><th>Total</th><th></th></tr></thead><tbody><tr v-for="(x,i) in documents" :key="i"><td><b>{{documentTypes.find(d=>d.id===x.documento_caja_chica_id)?.codigo}}</b><small>{{x.serie||'—'}}-{{x.numero||'—'}}</small></td><td>{{x.fecha_documento}}</td><td>{{x.codigo_persona}}<small>{{x.nombre_persona}}</small></td><td>{{categories.find(d=>d.id===x.rubro_caja_chica_id)?.codigo||'—'}} / {{destinations.find(d=>d.id===x.destino_movilidad_id)?.codigo||'—'}}</td><td>{{money(x.subtotal)}}</td><td>{{money(x.impuesto)}}</td><td>{{money(x.otros)}}</td><td><b>{{money(x.total)}}</b></td><td><button type="button" @click="open(i)">Editar</button> <button type="button" class="danger" @click="remove(i)">Quitar</button></td></tr></tbody></table></div></section><section class="totals"><span>Subtotal <b>S/ {{money(totals.subtotal)}}</b></span><span>Impuesto <b>S/ {{money(totals.impuesto)}}</b></span><span>Otros <b>S/ {{money(totals.otros)}}</b></span><span>Total <b>S/ {{money(totals.total)}}</b></span></section><footer class="actions"><RouterLink :to="listPath">Cancelar</RouterLink><button :disabled="saving">{{saving?'Guardando…':isEditing?'Actualizar rendición':'Guardar rendición'}}</button></footer></form><div v-if="modal" class="backdrop" @mousedown.self="modal=false"><section class="dialog"><header><h2>{{editing===null?'Agregar':'Editar'}} documento</h2><button @click="modal=false">×</button></header><div class="grid"><label>Tipo documento *<select v-model.number="doc.documento_caja_chica_id"><option :value="0">Seleccione</option><option v-for="x in documentTypes" :key="x.id" :value="x.id">{{x.codigo}} · {{x.detalle}}</option></select></label><label>Serie<input v-model="doc.serie" maxlength="20"></label><label>Número<input v-model="doc.numero" maxlength="30"></label><label>Fecha *<input v-model="doc.fecha_documento" type="date"></label><label>Tipo persona<select v-model="doc.tipo_persona" @change="resetPerson"><option value="PROVEEDOR">Proveedor</option><option value="TRABAJADOR">Trabajador</option></select></label><label class="full person">Buscar persona<span><input v-model="personQuery" placeholder="Código o nombre" @keyup.enter.prevent="search"><button type="button" @click="search">Buscar</button></span><i v-for="x in people" :key="x.id" @click="selectPerson(x)"><b>{{x.codigo}}</b> {{x.nombre}}</i><strong v-if="doc.codigo_persona">{{doc.codigo_persona}} · {{doc.nombre_persona}}</strong></label><label>Subtotal<input v-model.number="doc.subtotal" type="number" min="0" step=".01" @input="calculate"></label><label>Impuesto<input v-model.number="doc.impuesto" type="number" min="0" step=".01" @input="calculate"></label><label>Otros<input v-model.number="doc.otros" type="number" min="0" step=".01" @input="calculate"></label><label>Total<input :value="doc.total.toFixed(2)" readonly></label><label>Rubro<select v-model.number="doc.rubro_caja_chica_id"><option :value="null">Sin rubro</option><option v-for="x in categories" :key="x.id" :value="x.id">{{x.codigo}} · {{x.detalle}}</option></select></label><label>Destino<select v-model.number="doc.destino_movilidad_id"><option :value="null">Sin destino</option><option v-for="x in destinations" :key="x.id" :value="x.id">{{x.codigo}} · {{x.denominacion}}</option></select></label><label class="full">Glosa<input v-model="doc.glosa" maxlength="500"></label></div><footer><button class="soft" @click="modal=false">Cancelar</button><button @click="saveDocument">Guardar documento</button></footer></section></div></div></template>
<style scoped>.page{--a:#176d78;color:#344750}nav{margin-bottom:15px;font-size:.68rem}nav a{color:var(--a)}.hero,.card{padding:18px;border-radius:12px;background:#fff}.hero{display:flex;gap:14px;border-left:5px solid var(--a)}.hero>b{width:50px;height:50px;display:grid;place-items:center;border-radius:10px;color:#fff;background:var(--a)}h1,h2{margin:3px 0}.hero p{margin:0;color:#7c8b91;font-size:.65rem}.hero small{color:var(--a);font-size:.48rem}.flash{padding:10px;color:#9b3d48;background:#fdebee}.card{margin-top:12px}.card>header{display:flex;justify-content:space-between}.grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px}.full{grid-column:1/-1}label{display:grid;gap:5px;font-size:.5rem;font-weight:700}input,select{box-sizing:border-box;width:100%;padding:9px;border:1px solid #d5dfe2;border-radius:6px;background:#fff}button,.actions a{padding:8px 11px;border:0;border-radius:6px;color:#fff;background:var(--a);font-size:.5rem;text-decoration:none}.danger{background:#b74b54}.soft,.actions a{color:#607078;background:#edf2f3}.empty{padding:35px;text-align:center}.scroll{overflow:auto}table{width:100%;min-width:1000px;border-collapse:collapse;font-size:.47rem}th,td{padding:9px;border-bottom:1px solid #e3e9eb;text-align:left}th{color:#fff;background:#435d6c}td small{display:block}.totals{display:flex;justify-content:flex-end;gap:8px;margin-top:12px}.totals span{padding:12px;display:grid;background:#fff;font-size:.5rem}.totals b{font-size:.7rem}.actions{padding:15px 0;display:flex;justify-content:flex-end;gap:8px}.backdrop{position:fixed;z-index:100;inset:0;display:grid;place-items:center;background:#172b3d88}.dialog{width:min(950px,95%);max-height:90vh;padding:20px;box-sizing:border-box;border-radius:12px;background:#fff;overflow:auto}.dialog>header,.dialog>footer{display:flex;justify-content:space-between}.dialog>footer{margin-top:15px;justify-content:flex-end;gap:8px}.person span{display:flex}.person i{padding:7px;background:#f1f6f7;cursor:pointer}.person strong{padding:8px;color:var(--a);background:#e7f4f5}@media(max-width:800px){.grid{grid-template-columns:repeat(2,1fr)}}@media(max-width:500px){.grid{grid-template-columns:1fr}.full{grid-column:auto}}</style>
